-- ============================================================================
-- 20261014000200_popup_queries.sql
-- ============================================================================
-- Read paths: "open now" logic, card view, nearby search, event tracking.

-- ---------------------------------------------------------------------------
-- Opening hours logic (mirrors packages/shared/src/status.ts)
-- ---------------------------------------------------------------------------

-- Is the pop-up open at the given instant, in its own timezone?
create or replace function public.popup_is_open_at(p_popup_id uuid, p_at timestamptz default now())
returns boolean
language sql
stable
set search_path = public
as $$
  with p as (
    select id, timezone, starts_at, ends_at,
           (p_at at time zone timezone) as local_ts
    from public.popups
    where id = p_popup_id
  )
  select coalesce((
    select p_at >= p.starts_at and p_at < p.ends_at and (
      not exists (select 1 from public.popup_hours h where h.popup_id = p.id)
      or exists (
        select 1
        from public.popup_hours h
        where h.popup_id = p.id
          and (
            -- Opened today and still before closing (or closes after midnight).
            (h.weekday = extract(dow from p.local_ts)
              and p.local_ts::time >= h.opens
              and (h.closes <= h.opens or p.local_ts::time < h.closes))
            -- Opened yesterday and runs past midnight.
            or (h.weekday = (extract(dow from p.local_ts)::int + 6) % 7
              and h.closes <= h.opens
              and p.local_ts::time < h.closes)
          )
      )
    )
    from p
  ), false);
$$;

-- Open now, or opens later today.
create or replace function public.popup_is_open_today(p_popup_id uuid, p_at timestamptz default now())
returns boolean
language sql
stable
set search_path = public
as $$
  select public.popup_is_open_at(p_popup_id, p_at) or coalesce((
    select
      p.starts_at < ((p_at at time zone p.timezone)::date + 1)::timestamp at time zone p.timezone
      and p.ends_at > p_at
      and (
        not exists (select 1 from public.popup_hours h where h.popup_id = p.id)
        or exists (
          select 1 from public.popup_hours h
          where h.popup_id = p.id
            and h.weekday = extract(dow from p_at at time zone p.timezone)
            and h.opens > (p_at at time zone p.timezone)::time
            and ((p_at at time zone p.timezone)::date + h.opens) at time zone p.timezone < p.ends_at
        )
      )
    from public.popups p
    where p.id = p_popup_id
  ), false);
$$;

-- Israeli weekend window: Thursday 00:00 → Sunday 00:00 (local). From Thursday on, it starts "now".
create or replace function public.weekend_range(p_tz text default 'Asia/Jerusalem', p_at timestamptz default now())
returns tstzrange
language sql
stable
as $$
  with d as (
    select (p_at at time zone p_tz)::date as today,
           extract(dow from p_at at time zone p_tz)::int as dow
  )
  select tstzrange(
    case when dow >= 4 then p_at else (today + (4 - dow))::timestamp at time zone p_tz end,
    (today + (7 - dow))::timestamp at time zone p_tz
  )
  from d;
$$;

create or replace function public.popup_is_on_weekend(p_popup_id uuid, p_at timestamptz default now())
returns boolean
language sql
stable
set search_path = public
as $$
  select coalesce((
    select tstzrange(p.starts_at, p.ends_at) && public.weekend_range(p.timezone, p_at)
      and (
        not exists (select 1 from public.popup_hours h where h.popup_id = p.id)
        or exists (select 1 from public.popup_hours h where h.popup_id = p.id and h.weekday in (4, 5, 6))
      )
    from public.popups p
    where p.id = p_popup_id
  ), false);
$$;

-- ---------------------------------------------------------------------------
-- Card view: everything a pop-up card needs, in one row.
-- security_invoker = RLS of the caller applies (public sees only live, approved pop-ups).
-- ---------------------------------------------------------------------------
create or replace view public.popup_cards
with (security_invoker = true)
as
select
  p.id,
  p.slug,
  p.title,
  p.short_description,
  p.category,
  p.country_code,
  c.slug as city_slug,
  c.name_he as city_name_he,
  c.name_en as city_name_en,
  p.address,
  extensions.st_y(p.location::extensions.geometry) as lat,
  extensions.st_x(p.location::extensions.geometry) as lng,
  p.location,
  p.timezone,
  p.starts_at,
  p.ends_at,
  p.price_range,
  p.status,
  p.created_at,
  p.approved_at,
  (select i.url from public.popup_images i where i.popup_id = p.id order by i.sort_order, i.id limit 1) as cover_image_url,
  coalesce((
    select json_agg(json_build_object(
             'weekday', h.weekday,
             'opens', to_char(h.opens, 'HH24:MI'),
             'closes', to_char(h.closes, 'HH24:MI'))
           order by h.weekday, h.opens)
    from public.popup_hours h where h.popup_id = p.id
  ), '[]'::json) as hours
from public.popups p
join public.cities c on c.id = p.city_id;

-- ---------------------------------------------------------------------------
-- nearby_popups: live pop-ups around a point, nearest first, with distance in km.
-- filters (all optional): {"category": "food", "open_now": true, "today": true,
--                          "this_weekend": true, "free_only": true}
-- ---------------------------------------------------------------------------
create or replace function public.nearby_popups(
  lat double precision,
  lng double precision,
  radius_km double precision default 10,
  filters jsonb default '{}'::jsonb,
  max_results int default 100,
  locale text default 'he'
)
returns table (
  id uuid,
  slug text,
  title text,
  short_description text,
  category text,
  country_code text,
  city_slug text,
  city_name text,
  address text,
  lat double precision,
  lng double precision,
  timezone text,
  starts_at timestamptz,
  ends_at timestamptz,
  price_range public.price_range,
  cover_image_url text,
  hours json,
  distance_km double precision
)
language sql
stable
set search_path = public, extensions
as $$
  with origin as (
    select extensions.st_setsrid(extensions.st_makepoint(nearby_popups.lng, nearby_popups.lat), 4326)::extensions.geography as g,
           least(greatest(coalesce(nearby_popups.radius_km, 10), 0.1), 200) * 1000 as radius_m
  )
  select
    pc.id, pc.slug, pc.title, pc.short_description, pc.category, pc.country_code, pc.city_slug,
    case when nearby_popups.locale = 'he' then pc.city_name_he else pc.city_name_en end,
    pc.address, pc.lat, pc.lng, pc.timezone, pc.starts_at, pc.ends_at, pc.price_range,
    pc.cover_image_url, pc.hours,
    round((extensions.st_distance(pc.location, origin.g) / 1000)::numeric, 2)::double precision as distance_km
  from public.popup_cards pc, origin
  where pc.status = 'approved'
    and pc.ends_at > now()
    and extensions.st_dwithin(pc.location, origin.g, origin.radius_m)
    and (filters ->> 'category' is null or pc.category = filters ->> 'category')
    and (coalesce((filters ->> 'free_only')::boolean, false) = false or pc.price_range = 'free')
    and (coalesce((filters ->> 'open_now')::boolean, false) = false or public.popup_is_open_at(pc.id))
    and (coalesce((filters ->> 'today')::boolean, false) = false or public.popup_is_open_today(pc.id))
    and (coalesce((filters ->> 'this_weekend')::boolean, false) = false or public.popup_is_on_weekend(pc.id))
  order by extensions.st_distance(pc.location, origin.g)
  limit least(greatest(coalesce(nearby_popups.max_results, 100), 1), 300);
$$;

-- ---------------------------------------------------------------------------
-- Event tracking. Anyone (even logged-out) can record events for live pop-ups.
-- Views are de-duplicated per session per pop-up per hour so refreshes don't inflate scores.
-- ---------------------------------------------------------------------------
create or replace function public.track_popup_event(
  p_popup_id uuid,
  p_event_type public.popup_event_type,
  p_session_id text default null,
  p_surface text default null,
  p_promotion_id uuid default null
)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if not exists (select 1 from public.popups where id = p_popup_id and status = 'approved') then
    return;
  end if;

  if p_event_type in ('view', 'impression') and p_session_id is not null and exists (
    select 1 from public.popup_events
    where popup_id = p_popup_id
      and event_type = p_event_type
      and session_id = p_session_id
      and created_at > now() - interval '1 hour'
  ) then
    return;
  end if;

  insert into public.popup_events (popup_id, event_type, user_id, session_id, surface, promotion_id)
  values (p_popup_id, p_event_type, auth.uid(), left(p_session_id, 64), left(p_surface, 32), p_promotion_id);

  if p_promotion_id is not null then
    update public.promotions
       set impressions = impressions + (p_event_type = 'impression')::int,
           clicks = clicks + (p_event_type in ('click', 'navigate'))::int
     where id = p_promotion_id and popup_id = p_popup_id;
  end if;
end;
$$;

-- Per pop-up stats for its organizer (and admins).
create or replace function public.popup_stats(p_popup_id uuid, p_days int default 30)
returns table (views bigint, saves bigint, navigations bigint, shares bigint)
language sql
stable
security definer
set search_path = public
as $$
  select
    count(*) filter (where e.event_type = 'view'),
    count(*) filter (where e.event_type = 'save'),
    count(*) filter (where e.event_type = 'navigate'),
    count(*) filter (where e.event_type = 'share')
  from public.popup_events e
  where e.popup_id = p_popup_id
    and e.created_at > now() - make_interval(days => least(greatest(p_days, 1), 365))
    and (
      public.is_admin()
      or exists (
        select 1 from public.popups p
        where p.id = p_popup_id and p.organizer_id is not null and public.owns_organizer(p.organizer_id)
      )
    );
$$;

-- ============================================================================
-- 20261014000300_rls_and_storage.sql
-- ============================================================================
-- Row Level Security
--   * Everyone (even logged out): read approved, not-yet-ended pop-ups + reference data.
--   * Organizers: create pop-ups (always pending), read/edit their own.
--   * Admins: everything.

alter table public.countries enable row level security;
alter table public.cities enable row level security;
alter table public.categories enable row level security;
alter table public.profiles enable row level security;
alter table public.organizers enable row level security;
alter table public.popups enable row level security;
alter table public.popup_hours enable row level security;
alter table public.popup_images enable row level security;
alter table public.favorites enable row level security;
alter table public.popup_events enable row level security;
alter table public.promotions enable row level security;
alter table public.app_config enable row level security;

-- Explicit grants (RLS still decides which rows).
grant usage on schema public to anon, authenticated;
grant select on public.countries, public.cities, public.categories to anon, authenticated;
grant select on public.popups, public.popup_hours, public.popup_images, public.popup_cards to anon, authenticated;
grant insert, update, delete on public.popups, public.popup_hours, public.popup_images to authenticated;
grant select, insert, update, delete on public.profiles, public.organizers, public.favorites to authenticated;
grant select, insert, update, delete on public.promotions, public.app_config to authenticated;
grant select on public.popup_events to authenticated;
grant execute on function public.nearby_popups(double precision, double precision, double precision, jsonb, int, text) to anon, authenticated;
grant execute on function public.track_popup_event(uuid, public.popup_event_type, text, text, uuid) to anon, authenticated;
grant execute on function public.popup_stats(uuid, int) to authenticated;
grant execute on function public.popup_is_open_at(uuid, timestamptz) to anon, authenticated;
grant execute on function public.popup_is_open_today(uuid, timestamptz) to anon, authenticated;
grant execute on function public.popup_is_on_weekend(uuid, timestamptz) to anon, authenticated;
grant execute on function public.weekend_range(text, timestamptz) to anon, authenticated;

-- Reference data: public read, admin write.
create policy "countries are public" on public.countries for select using (true);
create policy "admins manage countries" on public.countries for all to authenticated
  using (public.is_admin()) with check (public.is_admin());
create policy "cities are public" on public.cities for select using (true);
create policy "admins manage cities" on public.cities for all to authenticated
  using (public.is_admin()) with check (public.is_admin());
create policy "categories are public" on public.categories for select using (true);
create policy "admins manage categories" on public.categories for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- Profiles: you see and edit your own. Role changes are blocked by a trigger below.
create policy "read own profile" on public.profiles for select to authenticated
  using (id = auth.uid() or public.is_admin());
create policy "update own profile" on public.profiles for update to authenticated
  using (id = auth.uid() or public.is_admin()) with check (id = auth.uid() or public.is_admin());

create or replace function public.guard_profile_role()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.role is distinct from old.role and auth.uid() is not null and not public.is_admin() then
    raise exception 'Only admins can change roles';
  end if;
  return new;
end;
$$;
create trigger profiles_guard_role before update on public.profiles
  for each row execute function public.guard_profile_role();

-- Organizers: owner + admins.
create policy "read own organizer" on public.organizers for select to authenticated
  using (owner_id = auth.uid() or public.is_admin());
-- Anonymous sessions (used for saving without sign-up) cannot become organizers.
create policy "create own organizer" on public.organizers for insert to authenticated
  with check (owner_id = auth.uid() and coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) = false);
create policy "update own organizer" on public.organizers for update to authenticated
  using (owner_id = auth.uid() or public.is_admin()) with check (owner_id = auth.uid() or public.is_admin());
create policy "admins delete organizers" on public.organizers for delete to authenticated
  using (public.is_admin());

-- Pop-ups
create policy "public reads live approved popups" on public.popups for select
  using (status = 'approved' and ends_at > now());
create policy "organizers read own popups" on public.popups for select to authenticated
  using (organizer_id is not null and public.owns_organizer(organizer_id));
create policy "admins read all popups" on public.popups for select to authenticated
  using (public.is_admin());
create policy "organizers create popups" on public.popups for insert to authenticated
  with check (organizer_id is not null and public.owns_organizer(organizer_id));
create policy "admins create popups" on public.popups for insert to authenticated
  with check (public.is_admin());
create policy "organizers edit own popups" on public.popups for update to authenticated
  using (organizer_id is not null and public.owns_organizer(organizer_id))
  with check (organizer_id is not null and public.owns_organizer(organizer_id));
create policy "admins edit popups" on public.popups for update to authenticated
  using (public.is_admin()) with check (public.is_admin());
create policy "admins delete popups" on public.popups for delete to authenticated
  using (public.is_admin());

-- Child rows (hours, images) follow their pop-up.
create or replace function public.can_edit_popup(p_popup_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.is_admin() or exists (
    select 1 from public.popups p
    where p.id = p_popup_id and p.organizer_id is not null and public.owns_organizer(p.organizer_id)
  );
$$;

create policy "hours readable with popup" on public.popup_hours for select
  using (exists (select 1 from public.popups p where p.id = popup_id));
create policy "editors manage hours" on public.popup_hours for all to authenticated
  using (public.can_edit_popup(popup_id)) with check (public.can_edit_popup(popup_id));

create policy "images readable with popup" on public.popup_images for select
  using (exists (select 1 from public.popups p where p.id = popup_id));
create policy "editors manage images" on public.popup_images for all to authenticated
  using (public.can_edit_popup(popup_id)) with check (public.can_edit_popup(popup_id));

-- Favorites: strictly your own (anonymous sessions included).
create policy "own favorites" on public.favorites for all to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());

-- Events: written only via track_popup_event(); readable by admins (organizers use popup_stats()).
create policy "admins read events" on public.popup_events for select to authenticated
  using (public.is_admin());

-- Promotions: admins manage; organizers can see promotions on their own pop-ups.
create policy "admins manage promotions" on public.promotions for all to authenticated
  using (public.is_admin()) with check (public.is_admin());
create policy "organizers read own promotions" on public.promotions for select to authenticated
  using (public.can_edit_popup(popup_id));

-- Config: admins only (feed functions read it with definer rights).
create policy "admins manage config" on public.app_config for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- ---------------------------------------------------------------------------
-- Storage: public bucket for pop-up images.
-- Uploads go to "<user id>/<file>" so each uploader owns their folder.
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('popup-images', 'popup-images', true, 8 * 1024 * 1024, array['image/jpeg', 'image/png', 'image/webp', 'image/heic'])
on conflict (id) do nothing;

create policy "popup images are public" on storage.objects for select
  using (bucket_id = 'popup-images');
create policy "upload into own folder" on storage.objects for insert to authenticated
  with check (bucket_id = 'popup-images' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "manage own uploads" on storage.objects for update to authenticated
  using (bucket_id = 'popup-images' and ((storage.foldername(name))[1] = auth.uid()::text or public.is_admin()));
create policy "delete own uploads" on storage.objects for delete to authenticated
  using (bucket_id = 'popup-images' and ((storage.foldername(name))[1] = auth.uid()::text or public.is_admin()));

-- ============================================================================
-- 20261015000100_feed_hot_sponsored.sql
-- ============================================================================
-- Feed queries: "Hot now" score, sponsored placement, and one card-list function used by every
-- list in the site (discover sections, "see all", search, category pages, map, saved).

-- ---------------------------------------------------------------------------
-- Hot score
--   score = views·w.view + saves·w.save + navigations·w.navigate + shares·w.share   (last window_hours)
--         + ending_soon_boost  (ends within 48h)
--         + new_boost          (opened within the last 72h)
--   Weights live in app_config.hot_score_weights, editable without code changes.
-- ---------------------------------------------------------------------------
create materialized view public.popup_hot_scores as
with cfg as (
  select coalesce((select value from public.app_config where key = 'hot_score_weights'), '{}'::jsonb) as w
),
ev as (
  select
    e.popup_id,
    count(*) filter (where e.event_type = 'view') as views,
    count(*) filter (where e.event_type = 'save') as saves,
    count(*) filter (where e.event_type = 'navigate') as navigations,
    count(*) filter (where e.event_type = 'share') as shares
  from public.popup_events e, cfg
  where e.created_at > now() - make_interval(hours => coalesce((cfg.w ->> 'window_hours')::int, 24))
  group by e.popup_id
)
select
  p.id as popup_id,
  coalesce(ev.views, 0) as views,
  coalesce(ev.saves, 0) as saves,
  coalesce(ev.navigations, 0) as navigations,
  coalesce(ev.shares, 0) as shares,
  (
    coalesce(ev.views, 0) * coalesce((cfg.w ->> 'view')::numeric, 1)
    + coalesce(ev.saves, 0) * coalesce((cfg.w ->> 'save')::numeric, 4)
    + coalesce(ev.navigations, 0) * coalesce((cfg.w ->> 'navigate')::numeric, 6)
    + coalesce(ev.shares, 0) * coalesce((cfg.w ->> 'share')::numeric, 3)
    + case when p.ends_at < now() + interval '48 hours' then coalesce((cfg.w ->> 'ending_soon_boost')::numeric, 15) else 0 end
    + case when p.starts_at between now() - interval '72 hours' and now() then coalesce((cfg.w ->> 'new_boost')::numeric, 10) else 0 end
  ) as score,
  now() as computed_at
from public.popups p
cross join cfg
left join ev on ev.popup_id = p.id
where p.status = 'approved' and p.ends_at > now();

create unique index popup_hot_scores_popup_idx on public.popup_hot_scores (popup_id);
revoke all on public.popup_hot_scores from anon, authenticated;

-- Refreshes the scores if they are older than 10 minutes. Called from feed reads, so the
-- ranking stays fresh without any scheduler; only one caller refreshes at a time.
create or replace function public.maybe_refresh_hot_scores(p_max_age interval default interval '10 minutes')
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_last timestamptz;
begin
  select max(computed_at) into v_last from public.popup_hot_scores;
  if v_last is not null and v_last > now() - p_max_age then
    return;
  end if;
  if pg_try_advisory_xact_lock(hashtext('popup_hot_scores')) then
    refresh materialized view concurrently public.popup_hot_scores;
  end if;
end;
$$;

-- Optional: if pg_cron is enabled (Supabase → Database → Extensions), refresh every 10 minutes too.
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    execute $cron$select cron.schedule('refresh-hot-scores', '*/10 * * * *',
      'select public.maybe_refresh_hot_scores(interval ''0 minutes'')')$cron$;
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- Sponsored items: at most one per `sponsored_every_n` items, placed first, then every N.
-- ---------------------------------------------------------------------------
create or replace function public.interleave_sponsored(p_organic jsonb, p_sponsored jsonb, p_every_n int, p_limit int)
returns jsonb
language plpgsql
immutable
as $$
declare
  v_out jsonb := '[]'::jsonb;
  v_sponsored_ids jsonb := coalesce((select jsonb_agg(s -> 'id') from jsonb_array_elements(p_sponsored) s), '[]'::jsonb);
  v_item jsonb;
  v_si int := 0;
  v_n int := greatest(coalesce(p_every_n, 5), 2);
begin
  for v_item in select value from jsonb_array_elements(coalesce(p_organic, '[]'::jsonb)) loop
    -- Don't show the same pop-up twice (once sponsored, once organic).
    continue when v_sponsored_ids @> jsonb_build_array(v_item -> 'id');
    if jsonb_array_length(v_out) % v_n = 0 and v_si < jsonb_array_length(p_sponsored) then
      v_out := v_out || jsonb_build_array(p_sponsored -> v_si);
      v_si := v_si + 1;
    end if;
    v_out := v_out || jsonb_build_array(v_item);
  end loop;
  -- Nothing organic at all: still show one sponsored item rather than an empty list.
  if jsonb_array_length(v_out) = 0 and jsonb_array_length(p_sponsored) > 0 then
    v_out := jsonb_build_array(p_sponsored -> 0);
  end if;
  return coalesce((select jsonb_agg(value order by ord) from jsonb_array_elements(v_out) with ordinality as x(value, ord) where ord <= p_limit), '[]'::jsonb);
end;
$$;

-- ---------------------------------------------------------------------------
-- popup_list: THE card list. Every list on the site calls this.
--   p_section: 'hot' | 'nearby' | 'weekend' | 'ending_soon' | 'all' | 'map'
--   p_filters: {"category": "food", "open_now": true, "today": true, "this_weekend": true,
--               "free_only": true, "query": "טאקו", "categories": ["food"], "ids": ["…uuid…"]}
-- Returns a JSON array of cards (same shape as PopupSummary in packages/shared/src/types.ts).
-- Sponsored items carry "is_sponsored": true and "promotion_id".
-- ---------------------------------------------------------------------------
create or replace function public.popup_list(
  p_section text default 'all',
  p_lat double precision default null,
  p_lng double precision default null,
  p_radius_km double precision default 10,
  p_filters jsonb default '{}'::jsonb,
  p_limit int default 20,
  p_country text default null,
  p_locale text default 'he'
)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  v_limit int := least(greatest(coalesce(p_limit, 20), 1), 300);
  v_every int := coalesce((select (value #>> '{}')::int from public.app_config where key = 'sponsored_every_n'), 5);
  v_placement public.promotion_placement := case p_section
    when 'hot' then 'hot_now'::public.promotion_placement
    when 'nearby' then 'nearby_top'::public.promotion_placement
    when 'map' then 'map_highlight'::public.promotion_placement
  end;
  v_origin extensions.geography := case when p_lat is not null and p_lng is not null
    then extensions.st_setsrid(extensions.st_makepoint(p_lng, p_lat), 4326)::extensions.geography end;
  v_radius_m double precision := least(greatest(coalesce(p_radius_km, 10), 0.1), 500) * 1000;
  v_f jsonb := coalesce(p_filters, '{}'::jsonb);
  v_query text := nullif(trim(v_f ->> 'query'), '');
  v_categories text[] := case when jsonb_typeof(v_f -> 'categories') = 'array'
    then array(select jsonb_array_elements_text(v_f -> 'categories')) end;
  v_ids uuid[] := case when jsonb_typeof(v_f -> 'ids') = 'array'
    then array(select jsonb_array_elements_text(v_f -> 'ids')::uuid) end;
  v_organic jsonb;
  v_sponsored jsonb;
begin
  if p_section not in ('hot', 'nearby', 'weekend', 'ending_soon', 'all', 'map') then
    raise exception 'unknown section %', p_section;
  end if;
  if p_section = 'nearby' and v_origin is null then
    return '[]'::jsonb;
  end if;

  perform public.maybe_refresh_hot_scores();

  with base as (
    select
      pc.*,
      case when v_origin is not null then extensions.st_distance(pc.location, v_origin) / 1000 end as dist_km,
      coalesce(hs.score, 0) as score,
      (select pr.id from public.promotions pr
        where v_placement is not null and pr.popup_id = pc.id and pr.placement = v_placement
          and pr.status = 'active' and now() >= pr.starts_at and now() < pr.ends_at
        order by pr.budget_amount desc limit 1) as promo_id
    from public.popup_cards pc
    left join public.popup_hot_scores hs on hs.popup_id = pc.id
    where pc.status = 'approved'
      and pc.ends_at > now()
      and (p_country is null or pc.country_code = p_country)
      and (v_ids is null or pc.id = any (v_ids))
      and (v_f ->> 'category' is null or pc.category = v_f ->> 'category')
      and (
        v_query is null and v_categories is null
        or (v_categories is not null and pc.category = any (v_categories))
        or (v_query is not null and (
          pc.title ilike '%' || v_query || '%'
          or pc.short_description ilike '%' || v_query || '%'
          or pc.address ilike '%' || v_query || '%'
          or pc.city_name_he ilike '%' || v_query || '%'
          or pc.city_name_en ilike '%' || v_query || '%'
        ))
      )
      and (coalesce((v_f ->> 'free_only')::boolean, false) = false or pc.price_range = 'free')
      and (coalesce((v_f ->> 'open_now')::boolean, false) = false or public.popup_is_open_at(pc.id))
      and (coalesce((v_f ->> 'today')::boolean, false) = false or public.popup_is_open_today(pc.id))
      and (coalesce((v_f ->> 'this_weekend')::boolean, false) = false or public.popup_is_on_weekend(pc.id))
      and (p_section not in ('nearby', 'map') or v_origin is null or extensions.st_dwithin(pc.location, v_origin, v_radius_m))
      and (p_section <> 'weekend' or public.popup_is_on_weekend(pc.id))
      and (p_section <> 'ending_soon' or (pc.ends_at <= now() + interval '72 hours' and pc.starts_at <= now()))
  ),
  cards as (
    select
      b.*,
      jsonb_build_object(
        'id', b.id,
        'slug', b.slug,
        'title', b.title,
        'short_description', b.short_description,
        'category', b.category,
        'country_code', b.country_code,
        'city_slug', b.city_slug,
        'city_name', case when p_locale = 'he' then b.city_name_he else b.city_name_en end,
        'address', b.address,
        'lat', b.lat,
        'lng', b.lng,
        'timezone', b.timezone,
        'starts_at', b.starts_at,
        'ends_at', b.ends_at,
        'price_range', b.price_range,
        'cover_image_url', b.cover_image_url,
        'hours', b.hours,
        'distance_km', round(b.dist_km::numeric, 2)
      ) as card
    from base b
  )
  select
    (select coalesce(jsonb_agg(o.card || jsonb_build_object(
              'is_sponsored', p_section = 'map' and o.promo_id is not null,
              'promotion_id', case when p_section = 'map' then o.promo_id end)
            order by o.ord), '[]'::jsonb)
       from (
         select c.card, c.promo_id,
           row_number() over (order by
             case when p_section = 'hot' then c.score end desc nulls last,
             case when p_section = 'ending_soon' then c.ends_at end asc nulls last,
             c.dist_km asc nulls last,
             case when p_section = 'weekend' then c.starts_at end asc nulls last,
             c.score desc,
             c.ends_at asc) as ord
         from cards c
       ) o
       where o.ord <= v_limit + 5),
    (select coalesce(jsonb_agg(s.card || jsonb_build_object('is_sponsored', true, 'promotion_id', s.promo_id)), '[]'::jsonb)
       from (
         select c.card, c.promo_id from cards c
         where p_section in ('hot', 'nearby') and c.promo_id is not null
         order by random()
         limit greatest(1, ceil(v_limit::numeric / greatest(v_every, 2))::int)
       ) s)
  into v_organic, v_sponsored;

  if p_section in ('hot', 'nearby') then
    return public.interleave_sponsored(v_organic, v_sponsored, v_every, v_limit);
  end if;
  return coalesce((select jsonb_agg(value order by ord) from jsonb_array_elements(v_organic) with ordinality x(value, ord) where ord <= v_limit), '[]'::jsonb);
end;
$$;

-- ---------------------------------------------------------------------------
-- discover_feed: everything the home page needs in one round trip.
-- "nearby" widens 10 → 25 → 50 km until it finds something; nearby_radius_km says which was used.
-- ---------------------------------------------------------------------------
create or replace function public.discover_feed(
  p_lat double precision default null,
  p_lng double precision default null,
  p_country text default 'IL',
  p_locale text default 'he'
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_nearby jsonb := '[]'::jsonb;
  v_radius int;
begin
  if p_lat is not null and p_lng is not null then
    foreach v_radius in array array[10, 25, 50] loop
      v_nearby := public.popup_list('nearby', p_lat, p_lng, v_radius, '{}', 10, p_country, p_locale);
      exit when jsonb_array_length(v_nearby) > 0;
    end loop;
  end if;
  return jsonb_build_object(
    'hot', public.popup_list('hot', p_lat, p_lng, null, '{}', 10, p_country, p_locale),
    'nearby', v_nearby,
    'nearby_radius_km', case when jsonb_array_length(v_nearby) > 0 then v_radius end,
    'weekend', public.popup_list('weekend', p_lat, p_lng, null, '{}', 12, p_country, p_locale),
    'ending_soon', public.popup_list('ending_soon', p_lat, p_lng, null, '{}', 12, p_country, p_locale)
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- popup_details: the full pop-up page. Ended pop-ups stay viewable (shared links shouldn't break);
-- pending/rejected ones only for their organizer and admins.
-- ---------------------------------------------------------------------------
create or replace function public.popup_details(p_slug text, p_locale text default 'he')
returns jsonb
language sql
stable
security definer
set search_path = public, extensions
as $$
  select jsonb_build_object(
    'id', p.id,
    'slug', p.slug,
    'title', p.title,
    'short_description', p.short_description,
    'description', p.description,
    'category', p.category,
    'country_code', p.country_code,
    'city_slug', c.slug,
    'city_name', case when p_locale = 'he' then c.name_he else c.name_en end,
    'address', p.address,
    'lat', extensions.st_y(p.location::extensions.geometry),
    'lng', extensions.st_x(p.location::extensions.geometry),
    'timezone', p.timezone,
    'starts_at', p.starts_at,
    'ends_at', p.ends_at,
    'price_range', p.price_range,
    'website_url', p.website_url,
    'instagram_url', p.instagram_url,
    'wheelchair_accessible', p.wheelchair_accessible,
    'parking_available', p.parking_available,
    'kid_friendly', p.kid_friendly,
    'accessibility_notes', p.accessibility_notes,
    'status', p.status,
    'organizer_name', o.name,
    'cover_image_url', (select i.url from public.popup_images i where i.popup_id = p.id order by i.sort_order, i.id limit 1),
    'images', coalesce((select jsonb_agg(jsonb_build_object('url', i.url, 'alt', i.alt) order by i.sort_order, i.id)
                        from public.popup_images i where i.popup_id = p.id), '[]'::jsonb),
    'hours', coalesce((select jsonb_agg(jsonb_build_object('weekday', h.weekday, 'opens', to_char(h.opens, 'HH24:MI'),
                                                           'closes', to_char(h.closes, 'HH24:MI')) order by h.weekday, h.opens)
                       from public.popup_hours h where h.popup_id = p.id), '[]'::jsonb)
  )
  from public.popups p
  join public.cities c on c.id = p.city_id
  left join public.organizers o on o.id = p.organizer_id
  where p.slug = p_slug
    and (p.status = 'approved' or public.can_edit_popup(p.id));
$$;

grant execute on function public.popup_list(text, double precision, double precision, double precision, jsonb, int, text, text) to anon, authenticated;
grant execute on function public.discover_feed(double precision, double precision, text, text) to anon, authenticated;
grant execute on function public.popup_details(text, text) to anon, authenticated;
grant execute on function public.maybe_refresh_hot_scores(interval) to anon, authenticated;

-- ============================================================================
-- 20261015000200_admin.sql
-- ============================================================================
-- Admin dashboard numbers. Admins only (returns null for everyone else).
create or replace function public.admin_stats()
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select case when not public.is_admin() then null else jsonb_build_object(
    'live', (select count(*) from public.popups where status = 'approved' and ends_at > now()),
    'pending', (select count(*) from public.popups where (status = 'pending' or needs_review) and ends_at > now()),
    'organizers', (select count(*) from public.organizers),
    'views_7d', (select count(*) from public.popup_events where event_type = 'view' and created_at > now() - interval '7 days'),
    'saves_7d', (select count(*) from public.popup_events where event_type = 'save' and created_at > now() - interval '7 days'),
    'navigations_7d', (select count(*) from public.popup_events where event_type = 'navigate' and created_at > now() - interval '7 days'),
    'top', coalesce((
      select jsonb_agg(t order by t.views desc)
      from (
        select p.id, p.slug, p.title, count(*) as views
        from public.popup_events e join public.popups p on p.id = e.popup_id
        where e.event_type = 'view' and e.created_at > now() - interval '7 days'
        group by p.id, p.slug, p.title
        order by count(*) desc
        limit 10
      ) t
    ), '[]'::jsonb)
  ) end;
$$;

grant execute on function public.admin_stats() to authenticated;

-- ============================================================================
-- seed.sql
-- ============================================================================
-- WHATS POPPIN — seed data
-- All dates are relative to the day you run the seed, so "open now", "ending soon" and
-- "this weekend" always have content. Re-run `supabase db reset` to refresh them.
-- Images are Unsplash placeholders; the app shows a category-colored fallback if one fails.

-- ---------------------------------------------------------------------------
-- Reference data
